```python
def vis_meny():
    print("\n=== Kalkulator ===")
    print("1. Addere")
    print("2. Subtrahere")
    print("3. Multiplisere")
    print("4. Dividere")
    print("5. Avslutte")
    return input("Velg (1-5): ")

def adder(a, b):
    return a + b

def subtraher(a, b):
    return a - b

def multipliser(a, b):
    return a * b

def divider(a, b):
    if b == 0:
        return "Feil: Divisjon med null!"
    return a / b

def hent_tall():
    a = float(input("Første tall: "))
    b = float(input("Andre tall: "))
    return a, b

# Hovedløkke
while True:
    valg = vis_meny()

    if valg == "5":
        print("Ha det bra!")
        break

    if valg not in ["1", "2", "3", "4"]:
        print("Ugyldig valg!")
        continue

    a, b = hent_tall()

    if valg == "1":
        print(f"Resultat: {adder(a, b)}")
    elif valg == "2":
        print(f"Resultat: {subtraher(a, b)}")
    elif valg == "3":
        print(f"Resultat: {multipliser(a, b)}")
    elif valg == "4":
        print(f"Resultat: {divider(a, b)}")
```

Programmet bruker separate funksjoner for meny, regneart og input. Hovedløkken med while True og break styrer programflyten.
